def total(a, i=0):
    if i == len(a):
        return 0
    return a[i] + total(a, i + 1)

def biggest(a, i=0):
    if i == len(a) - 1:
        return a[i]
    rest = biggest(a, i + 1)
    return a[i] if a[i] > rest else rest

def bsearch(a, x, lo, hi):
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if a[mid] == x:
        return mid
    if a[mid] < x:
        return bsearch(a, x, mid + 1, hi)
    return bsearch(a, x, lo, mid - 1)

a = [3, 8, 1, 6]
print(total(a), biggest(a))
b = [2, 5, 8, 12, 16, 23, 38]
